/* 
  Radio.scss 
  - Includes all default styles for the Radio component
*/
.form-radio {
  font-size: 0.6rem;
  display: block;
  line-height: 1.2rem;
  margin: 0.2rem 0;
  min-height: 1.2rem;
  padding: 0.1rem 0.4rem 0.1rem 1.2rem;
  position: relative;
}
.form-radio input {
  clip: rect(0, 0, 0, 0);
  height: 1px;
  margin: -1px;
  overflow: hidden;
  position: absolute;
  width: 1px;
}
.form-radio input:focus + .form-icon {
  border-color: #a6a6a6;
}
.form-radio input:checked + .form-icon {
  background: #f4f4f4;
  border-color: #0078d4;
  box-shadow: none;
}
.form-radio .form-icon {
  border: 0.05rem solid #adadad;
  cursor: pointer;
  display: inline-block;
  position: absolute;
  transition: background 0.2s, border 0.2s, box-shadow 0.2s, color 0.2s;
}
.form-radio .form-icon {
  background: #f4f4f4;
  height: 0.8rem;
  left: 0;
  top: 0.3rem;
  width: 0.8rem;
}
.form-radio input:active + .form-icon {
  background: #f7f7f7;
}
.form-radio .form-icon {
  border-radius: 50%;
}
.form-radio input:checked + .form-icon::before {
  background: #0078d4;
  border-radius: 50%;
  content: "";
  height: 8px;
  left: 50%;
  position: absolute;
  top: 50%;
  transform: translate(-50%, -50%);
  width: 8px;
}
.has-error .form-radio .form-icon,
.form-radio.is-error .form-icon {
  border-color: #e81123;
}
.has-error .form-radio input:checked + .form-icon,
.form-radio.is-error input:checked + .form-icon {
  border-color: #e81123;
}
.has-error .form-radio input:checked + .form-icon::before,
.form-radio.is-error input:checked + .form-icon::before {
  background: #e81123;
}
.has-error .form-radio input:focus + .form-icon,
.form-radio.is-error input:focus + .form-icon {
  box-shadow: 0 0 0 0.1rem rgba(232, 17, 35, 0.2);
  border-color: #e81123;
}
.form-radio input:disabled + .form-icon,
.form-radio input.disabled + .form-icon {
  background: #f7f7f7;
  cursor: not-allowed;
  opacity: 0.5;
}

/* 
  Checkbox.scss 
  - Includes all default styles for the Checkbox component
*/
.form-checkbox {
  font-size: 13px;
  display: block;
  line-height: 1.2rem;
  margin: 0.2rem 0;
  min-height: 1.2rem;
  padding: 0.1rem 0.4rem 0.1rem 1.2rem;
  position: relative;
}
.form-checkbox input {
  clip: rect(0, 0, 0, 0);
  height: 1px;
  margin: -1px;
  overflow: hidden;
  position: absolute;
  width: 1px;
}
.form-checkbox input:focus + .form-icon {
  border-color: #a6a6a6;
}
.form-checkbox input:checked + .form-icon {
  background: #f4f4f4;
  border-color: #0078d4;
  box-shadow: none;
}
.form-checkbox .form-icon {
  border: 0.05rem solid #adadad;
  cursor: pointer;
  display: inline-block;
  position: absolute;
  transition: background 0.2s, border 0.2s, box-shadow 0.2s, color 0.2s;
}
.form-checkbox .form-icon {
  background: #f4f4f4;
  height: 0.8rem;
  left: 0;
  top: 0.3rem;
  width: 0.8rem;
}
.form-checkbox input:active + .form-icon {
  background: #f7f7f7;
}
.form-checkbox .form-icon {
  border-color: #333333;
  border-radius: none;
}
.form-checkbox input:checked + .form-icon {
  background-color: #0078d4;
}
.form-checkbox input:checked + .form-icon::before {
  background-clip: padding-box;
  border: 0.1rem solid #f4f4f4;
  border-left-width: 0;
  border-top-width: 0;
  content: "";
  height: 9px;
  left: 50%;
  margin-left: -3px;
  margin-top: -6px;
  position: absolute;
  top: 50%;
  transform: rotate(45deg);
  width: 6px;
}
.has-error .form-checkbox,
.form-checkbox.is-error {
  color: #e81123;
}
.has-error .form-checkbox .form-icon,
.form-checkbox.is-error .form-icon {
  border-color: #e81123;
}
.has-error .form-checkbox input:checked + .form-icon,
.form-checkbox.is-error input:checked + .form-icon {
  background: #e81123;
  border-color: #e81123;
}
.has-error .form-checkbox input:focus + .form-icon,
.form-checkbox.is-error input:focus + .form-icon {
  box-shadow: 0 0 0 0.1rem rgba(232, 17, 35, 0.2);
  border-color: #e81123;
}
.has-error .form-checkbox input:indeterminate + .form-icon,
.form-checkbox.is-error input:indeterminate + .form-icon {
  background: #e81123;
  border-color: #e81123;
}
.form-checkbox input:disabled + .form-icon,
.form-checkbox input.disabled + .form-icon {
  background: #f7f7f7;
  cursor: not-allowed;
  opacity: 0.5;
}
.form-checkbox input:checked:disabled + .form-icon,
.form-checkbox input:checked.disabled + .form-icon {
  border: 1px solid #a6a6a6;
}
.form-checkbox input:checked:disabled + .form-icon::before,
.form-checkbox input:checked.disabled + .form-icon::before {
  border-color: #a6a6a6;
}

/* 
  Button.scss 
  - Includes all default styles for the button component
*/
.btn {
  position: relative;
  -webkit-font-smoothing: antialiased;
  background-color: #f4f4f4;
  border: none;
  color: #333333;
  font-size: 13px;
  font-weight: 600;
  box-sizing: border-box;
  text-align: center;
  text-decoration: none;
  cursor: pointer;
  vertical-align: top;
  padding-top: 0;
  padding-right: 0.8rem;
  padding-left: 0.8rem;
  padding-bottom: 0;
  display: inline-block;
  height: 1.8rem;
  min-width: 4rem;
  line-height: 1.2rem;
  outline: transparent;
  border: 0.05rem solid transparent;
  border-image: initial;
  border-radius: 0;
  user-select: none;
  white-space: nowrap;
}
.btn:focus,
.btn:hover {
  background: #dbdbdb;
  text-decoration: none;
}
.btn[disabled],
.btn:disabled,
.btn.disabled {
  cursor: default;
  opacity: 0.5;
  pointer-events: none;
}
.btn.btn-primary {
  background-color: #f2c811;
  color: #212121;
}
.btn.btn-primary:focus,
.btn.btn-primary:hover {
  background: #ddb60c;
}
.btn.btn-secondary {
  background-color: #0078d4;
  color: #f4f4f4;
}
.btn.btn-secondary:focus,
.btn.btn-secondary:hover {
  background: #006abb;
}
.btn.btn-disabled {
  background-color: #f4f4f4;
  color: #a6a6a6;
}
.btn.btn-disabled:focus,
.btn.btn-disabled:hover {
  cursor: default;
  background: #e7e7e7;
}
.btn.btn-action {
  background-color: #212121;
  color: #f4f4f4;
}
.btn.btn-action:focus,
.btn.btn-action:hover {
  background: #2e2e2e;
}
.btn.btn-success {
  background: #bad80a;
  border-color: #adc909;
  color: #f4f4f4;
}
.btn.btn-success:focus {
  box-shadow: 0 0 0 0.1rem rgba(186, 216, 10, 0.2);
}
.btn.btn-success:focus,
.btn.btn-success:hover {
  background: #b2ce0a;
  border-color: #a5c009;
  color: #f4f4f4;
}
.btn.btn-success:active,
.btn.btn-success.active {
  background: #9db608;
  border-color: #90a708;
  color: #f4f4f4;
}
.btn.btn-success.loading::after {
  border-bottom-color: #f4f4f4;
  border-left-color: #f4f4f4;
}
.btn.btn-error {
  background: #e81123;
  border-color: #da1021;
  color: #f4f4f4;
}
.btn.btn-error:focus {
  box-shadow: 0 0 0 0.1rem rgba(232, 17, 35, 0.2);
}
.btn.btn-error:focus,
.btn.btn-error:hover {
  background: #de1022;
  border-color: #d00f1f;
  color: #f4f4f4;
}
.btn.btn-error:active,
.btn.btn-error.active {
  background: #c70f1e;
  border-color: #b80e1c;
  color: #f4f4f4;
}
.btn.btn-error.loading::after {
  border-bottom-color: #f4f4f4;
  border-left-color: #f4f4f4;
}
.btn.btn-link {
  background: transparent;
  border-color: transparent;
  color: #0078d4;
}
.btn.btn-link:focus,
.btn.btn-link:hover,
.btn.btn-link:active,
.btn.btn-link.active {
  color: #005ba1;
}
.btn.btn-sm {
  font-size: 11px;
  height: 1.4rem;
  padding: 0.05rem 0.3rem;
}
.btn.btn-lg {
  font-size: 16px;
  height: 2rem;
  padding: 0.35rem 0.6rem;
}
.btn.btn-block {
  display: block;
  width: 100%;
}
.btn.btn-action {
  width: 1.8rem;
  padding-left: 0;
  padding-right: 0;
}
.btn.btn-action.btn-sm {
  width: 1.4rem;
}
.btn.btn-action.btn-lg {
  width: 2rem;
}
.btn .btn-group {
  display: inline-flex;
  flex-wrap: wrap;
}
.btn .btn-group .btn {
  flex: 1 0 auto;
}
.btn .btn-group .btn:first-child:not(:last-child) {
  border-bottom-right-radius: 0;
  border-top-right-radius: 0;
}
.btn .btn-group .btn:not(:first-child):not(:last-child) {
  border-radius: 0;
  margin-left: -0.05rem;
}
.btn .btn-group .btn:last-child:not(:first-child) {
  border-bottom-left-radius: 0;
  border-top-left-radius: 0;
  margin-left: -0.05rem;
}
.btn .btn-group .btn:focus,
.btn .btn-group .btn:hover,
.btn .btn-group .btn:active,
.btn .btn-group .btn.active {
  z-index: 1;
}
.btn .btn-group.btn-group-block {
  display: flex;
}
.btn .btn-group.btn-group-block .btn {
  flex: 1 0 0;
}

/* 
  Switch.scss 
  - Includes all default styles for the Switch component
*/
.form-switch {
  font-size: 0.6rem;
  display: block;
  line-height: 1.2rem;
  margin: 0.2rem 0;
  min-height: 1.2rem;
  padding: 0.1rem 0.4rem 0.1rem 1.2rem;
  position: relative;
}
.form-switch input {
  clip: rect(0, 0, 0, 0);
  height: 1px;
  margin: -1px;
  overflow: hidden;
  position: absolute;
  width: 1px;
}
.form-switch input:focus + .form-icon {
  border-color: #a6a6a6;
}
.form-switch input:checked + .form-icon {
  background: #f4f4f4;
  border-color: #0078d4;
  box-shadow: none;
}
.form-switch .form-icon {
  border: 0.05rem solid #adadad;
  cursor: pointer;
  display: inline-block;
  position: absolute;
  transition: background 0.2s, border 0.2s, box-shadow 0.2s, color 0.2s;
}
.form-switch span {
  padding-left: 0.8rem;
}
.form-switch .form-icon {
  background: #f4f4f4;
  background-clip: padding-box;
  border-radius: 0.45rem;
  height: 0.9rem;
  left: 0;
  width: 1.6rem;
  border-color: #333333;
  top: 0.25rem;
}
.form-switch .form-icon::before {
  background: #333333;
  border-radius: 50%;
  content: "";
  display: block;
  height: 0.6rem;
  left: 3px;
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  transition: background 0.2s, border 0.2s, box-shadow 0.2s, color 0.2s, left 0.2s;
  width: 0.6rem;
}
.form-switch input:checked + .form-icon {
  background-color: #0078d4;
  border: none;
}
.form-switch input:checked + .form-icon::before {
  background-color: #f4f4f4;
  left: 16px;
}
.form-switch input:active + .form-icon::before {
  background-color: #0078d4;
}
.has-error .form-switch .form-icon,
.form-switch.is-error .form-icon {
  border-color: #e81123;
}
.has-error .form-switch .form-icon::before,
.form-switch.is-error .form-icon::before {
  background-color: #e81123;
}
.has-error .form-switch input:checked + .form-icon,
.form-switch.is-error input:checked + .form-icon {
  background: #e81123;
  border-color: #e81123;
}
.has-error .form-switch input:focus + .form-icon,
.form-switch.is-error input:focus + .form-icon {
  box-shadow: 0 0 0 0.1rem rgba(232, 17, 35, 0.2);
  border-color: #e81123;
}
.form-switch input:disabled + .form-icon,
.form-switch input.disabled + .form-icon {
  opacity: 0.5;
}
.form-switch input:checked:disabled + .form-icon,
.form-switch input:checked.disabled + .form-icon {
  opacity: 0.5;
}
.form-switch.mini .form-icon {
  height: 0.1rem;
  width: 1.3rem;
  top: 0.5rem;
}
.form-switch.mini .form-icon::before {
  height: 0.6rem;
  width: 0.6rem;
  left: -1px;
  background-color: #FFF;
  border: 2px #333 solid;
}
.form-switch.mini input:active + .form-icon::before {
  background-color: #333;
}
.form-switch.mini input:focus + .form-icon {
  border-color: #333;
}
.form-switch.mini input:checked + .form-icon::before {
  left: 14px;
  background-color: #0078d4;
  border: none;
}
.form-switch.mini.has-error .form-switch.mini .form-icon::before,
.form-switch.mini.is-error .form-icon::before {
  border-color: #e81123;
}
.form-switch.mini.has-error .form-switch.mini input:checked + .form-icon::before,
.form-switch.mini.is-error input:checked + .form-icon::before {
  background: #e81123;
}

/* 
  Input.scss 
  - Includes all default styles for the Input component
*/
.form-input {
  box-shadow: none;
  background: none transparent;
  margin: 0;
  padding: 0 0.6rem;
  box-sizing: border-box;
  background-image: initial;
  border: 0.05rem solid #a6a6a6;
  border-radius: 0;
  color: #333333;
  display: block;
  font-size: 13px;
  text-overflow: ellipsis;
  outline: 0px;
  height: 1.8rem;
  line-height: 1.2rem;
  max-width: 100%;
  position: relative;
  transition: background 0.2s, border 0.2s, box-shadow 0.2s, color 0.2s;
  width: 100%;
  margin-top: 6px;
}
.form-input:hover {
  border-color: #333333;
}
.form-input:focus {
  border-color: #0078d4;
}
.form-input::placeholder {
  color: #a6a6a6;
  font-size: 13px;
}
.form-input.input-inline {
  display: inline-block;
  vertical-align: middle;
  width: auto;
}
.form-input[type=file] {
  height: auto;
}
.has-icon-left,
.has-icon-right {
  position: relative;
}
.has-icon-left .form-icon,
.has-icon-right .form-icon {
  height: 0.8rem;
  margin: 0 0.25rem;
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 0.8rem;
  z-index: 2;
}
.has-icon-left .form-icon {
  left: 0.05rem;
}
.has-icon-left .form-input {
  padding-left: 1.3rem;
}
.has-icon-right .form-icon {
  right: 0.05rem;
}
.has-icon-right .form-input {
  padding-right: 1.3rem;
}
.has-success .form-input,
.form-input.is-success {
  background: #fdfef2;
  border-color: #bad80a;
}
.has-success .form-input:focus,
.form-input.is-success:focus {
  box-shadow: 0 0 0 0.1rem rgba(186, 216, 10, 0.2);
}
.has-error .form-input,
.form-input.is-error {
  background: white;
  border-color: #e81123;
  color: #e81123;
}
.has-error .form-input:focus,
.form-input.is-error:focus {
  box-shadow: 0 0 0 0.1rem rgba(232, 17, 35, 0.2);
}
.form-input:not(:placeholder-shown):invalid {
  border-color: #e81123;
  color: #e81123;
}
.form-input:not(:placeholder-shown):invalid:focus {
  box-shadow: 0 0 0 0.1rem rgba(232, 17, 35, 0.2);
  background: white;
}
.form-input:not(:placeholder-shown):invalid + .form-input-hint {
  color: #e81123;
}
.form-input:disabled,
.form-input.disabled,
.bf-ui-form-select:disabled,
.bf-ui-form-select.disabled {
  background-color: #f7f7f7;
  cursor: not-allowed;
  opacity: 0.5;
}
.form-input[readonly] {
  background-color: #ffffff;
}
textarea.form-input,
textarea.form-input.input-lg,
textarea.form-input.input-sm {
  padding: 0 0.6rem;
  height: auto;
}

/* 
  MultiSelect.scss 
  - Includes all default styles for the MultiSelectt component
*/
/* 
  menu.scss 
  - Includes all default styles for rendering menus
*/
.menu {
  box-shadow: 0 0.05rem 0.2rem rgba(33, 33, 33, 0.3);
  background: #f4f4f4;
  border-radius: 0.1rem;
  list-style: none;
  margin: 0;
  min-width: 180px;
  padding: 0.4rem;
  transform: translateY(0.2rem);
  z-index: 300;
}
.menu.menu-nav {
  background: transparent;
  box-shadow: none;
}
.menu .menu-item {
  margin-top: 0;
  padding: 0;
  text-decoration: none;
  user-select: none;
}
.menu .menu-item > a {
  border-radius: 0.1rem;
  color: inherit;
  display: block;
  margin: 0 -0.4rem;
  padding: 0.2rem 0.4rem;
  text-decoration: none;
}
.menu .menu-item > a:focus,
.menu .menu-item > a:hover {
  background: #0078d4;
  color: #f2c811;
}
.menu .menu-item > a:active,
.menu .menu-item > a.active {
  background: #0078d4;
  color: #f2c811;
}
.menu .menu-item .form-checkbox,
.menu .menu-item .form-radio,
.menu .menu-item .form-switch {
  margin: 0.1rem 0;
}
.menu .menu-item + .menu-item {
  margin-top: 0.2rem;
}
.menu .menu-item > button {
  font-size: 13px;
  width: 100%;
  padding: 6px 12px;
  justify-content: flex-start;
  background-color: transparent;
  text-align: left;
  border: 0;
  margin-bottom: 0;
  display: flex;
  flex-direction: column;
}
.menu .menu-item > button:hover {
  color: #333;
  background: #f4f4f4;
  outline: 0;
}
.menu .menu-item > button:focus {
  outline: 0;
}
.menu .menu-item > button.active,
.menu .menu-item > button:active {
  background: #d4ecff;
}
.menu .menu-item > button .label-text {
  font-size: 14px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  text-align: left;
}
.menu .menu-item > button .label-desc {
  font-size: 11px;
  color: #989898;
  line-height: 16px;
}
.menu .menu-badge {
  float: right;
  padding: 0.2rem 0;
}
.menu .menu-badge .btn {
  margin-top: -0.1rem;
}
.form-multi-select {
  position: relative;
  appearance: none;
  border: 0.05rem solid #a6a6a6;
  border-radius: 0.1rem;
  color: inherit;
  font-size: 0.6rem;
  min-height: 1.8rem;
  line-height: 1.2rem;
  outline: none;
  margin-top: 0.4rem;
  padding: 0.25rem 0.4rem;
  vertical-align: middle;
  width: 100%;
  background: transparent;
}
.form-multi-select:hover {
  border-color: #333333;
}
.form-multi-select:focus {
  border-color: #0078d4;
}
.form-multi-select.select-sm {
  font-size: 11px;
  height: 1.4rem;
  padding: 0.05rem 1.1rem 0.05rem 0.3rem;
}
.form-multi-select.select-lg {
  font-size: 16px;
  height: 2rem;
  padding: 0.35rem 1.4rem 0.35rem 0.6rem;
}
.form-multi-select[size],
.form-multi-select[multiple] {
  height: auto;
  padding: 0.25rem 0.4rem;
}
.form-multi-select[size] option,
.form-multi-select[multiple] option {
  padding: 0.1rem 0.2rem;
}
.form-multi-select:not([multiple]):not([size]) {
  background: transparent url("data:image/svg+xml;charset=utf8,%3Csvg%20xmlns='http://www.w3.org/2000/svg'%20viewBox='0%200%204%205'%3E%3Cpath%20fill='%23667189'%20d='M2%200L0%202h4zm0%205L0%203h4z'/%3E%3C/svg%3E") no-repeat right 0.35rem center / 0.4rem 0.5rem;
  padding-right: 1.2rem;
}
.has-success .form-multi-select,
.form-multi-select.is-success {
  background: #fdfef2;
  border-color: #bad80a;
}
.has-success .form-multi-select:focus,
.form-multi-select.is-success:focus {
  box-shadow: 0 0 0 0.1rem rgba(186, 216, 10, 0.2);
}
.has-error .form-multi-select,
.form-multi-select.is-error {
  background: white;
  border-color: #e81123;
  color: #e81123;
}
.has-error .form-multi-select:focus,
.form-multi-select.is-error:focus {
  box-shadow: 0 0 0 0.1rem rgba(232, 17, 35, 0.2);
}
.form-multi-select:disabled,
.form-multi-select.disabled {
  background-color: #f7f7f7 !important;
  cursor: not-allowed;
  opacity: 0.5;
}
.form-multi-select .menu {
  border: 1px solid #e6e6e6;
  border-radius: 0;
  box-shadow: none;
  margin-top: 2px;
  left: 0;
  right: 0;
