/* CanvasGrid */
.scrollable-thickness .dvn-scroller::-webkit-scrollbar {
  height: 15px !important;
  width: 15px !important;
}
.performance-switch {
  display: flex;
  cursor: pointer;
}
.performance-switch .switch {
  position: relative;
  display: block;
  width: 40px;
  height: 20px;
  padding: 3px;
  border-radius: 18px;
  cursor: pointer;
  box-sizing: content-box;
}
.performance-switch .switch .dark {
  border-color: #f5f5f5;
}
.performance-switch .switch-input {
  position: absolute;
  top: 0;
  left: 0;
  opacity: 0;
  box-sizing: content-box;
}
.performance-switch .switch-label {
  position: relative;
  display: block;
  height: inherit;
  font-size: 8px;
  border-radius: inherit;
  border: 1px solid #333333;
}
.performance-switch .switch-label:before,
.performance-switch .switch-label:after {
  position: absolute;
  top: 50%;
  margin-top: -0.5em;
  line-height: 1;
}
.performance-switch .switch-label:before {
  content: attr(data-off);
  right: 7px;
  color: #333333;
}
.performance-switch .switch-label.dark:before {
  color: #f5f5f5 !important;
}
.performance-switch .switch-label:after {
  content: attr(data-on);
  left: 7px;
  color: #ffffff;
  opacity: 0;
}
.performance-switch .switch-input:checked ~ .switch-label {
  background: #0078d4;
  border: unset !important;
}
.performance-switch .switch-input:checked ~ .switch-label:before {
  opacity: 0;
}
.performance-switch .switch-input:checked ~ .switch-label:after {
  opacity: 1;
}
.performance-switch .switch-handle {
  position: absolute;
  top: 7px;
  left: 7px;
  width: 13px;
  height: 13px;
  border-radius: 100%;
  background: #333333;
}
.performance-switch .switch-handle .inner-icon {
  font-size: 10px;
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
}
.performance-switch .switch-handle.active {
  background: #ffffff !important;
}
.performance-switch .switch-input:checked ~ .switch-handle {
  left: 25px;
}
.performance-switch .performance-switch-label {
  display: flex;
  align-items: center;
}
.performance-switch .performance-switch-label .label-style {
  font-size: 13px;
  padding-left: 5px;
}
.performance-switch .switch-handle.dark {
  background-color: #f5f5f5;
}
.performance-disabled {
  opacity: 0.5 !important;
}
.performance-disabled > div {
  pointer-events: none;
}
